# Refactor: Duplicated dev/prod → module + `for_each` (zero-diff)

## Layout

```
modules/
  webapp/          # one instance per environment
    main.tf
    variables.tf
    outputs.tf
prod.tfvars
dev.tfvars
main.tf
moves.tf
```

## `modules/webapp/main.tf`

```hcl
resource "aws_s3_bucket" "assets" {
  bucket = "${var.env}-app-assets"
}

resource "aws_s3_bucket_versioning" "assets" {
  bucket = aws_s3_bucket.assets.id
  versioning_configuration { status = "Enabled" }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "assets" {
  bucket = aws_s3_bucket.assets.id
  rule {
    apply_server_side_encryption_by_default { sse_algorithm = "AES256" }
  }
}

resource "aws_s3_bucket_public_access_block" "assets" {
  bucket                  = aws_s3_bucket.assets.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_replication_configuration" "assets" {
  count  = var.enable_replication ? 1 : 0
  bucket = aws_s3_bucket.assets.id
  role   = aws_iam_role.replication[0].arn
  # ... rule: src prefix "" -> dest us-west-2 bucket
}

resource "aws_db_instance" "postgres" {
  identifier             = "${var.env}-app-db"
  instance_class         = var.db_instance_class
  engine                 = "postgres"
  allocated_storage      = 20
  multi_az               = var.db_multi_az
  storage_encrypted      = var.db_multi_az # prod only per spec
  publicly_accessible    = false
  deletion_protection    = true
  backup_retention_period = 7
  username               = var.db_user
  password               = var.db_password # from SOPS-decrypted var
}

resource "aws_iam_role" "service" {
  # OIDC trust for prod, plain assume for dev — driven by var.oidc_provider
}

resource "aws_eks_cluster" "this" { name = "${var.env}-eks" /* region via provider */ }

resource "aws_eks_node_group" "this" {
  cluster_name    = aws_eks_cluster.this.name
  node_group_name = "default"
  instance_types  = [var.node_instance_type]
  desired_size    = var.node_count
  min_size        = var.node_count
  max_size        = var.node_count + 1
}

resource "aws_cloudfront_distribution" "cdn" {
  # 443 listener via default; ACM cert, origin ALB/bucket per env
}
```

## `modules/webapp/variables.tf`

```hcl
variable "env"                { type = string }
variable "db_instance_class"  { type = string }
variable "db_multi_az"        { type = bool, default = false }
variable "db_user"            { type = string }
variable "db_password"        { type = string, sensitive = true }
variable "node_instance_type" { type = string }
variable "node_count"         { type = number }
variable "enable_replication" { type = bool, default = false }
variable "oidc_provider"      { type = string, default = null }
```

## `main.tf` — one block via `for_each`

```hcl
locals {
  envs = {
    dev = {
      node_count         = 2
      node_instance_type = "t3.medium"
      db_instance_class  = "db.t3.micro"
      db_multi_az        = false
      enable_replication = false
    }
    prod = {
      node_count         = 4
      node_instance_type = "t3.large"
      db_instance_class  = "db.t3.medium"
      db_multi_az        = true
      enable_replication = true
    }
  }
}

module "webapp" {
  for_each = local.envs
  source   = "./modules/webapp"

  env                = each.key
  node_count         = each.value.node_count
  node_instance_type = each.value.node_instance_type
  db_instance_class  = each.value.db_instance_class
  db_multi_az        = each.value.db_multi_az
  enable_replication = each.value.enable_replication
  db_user            = var.db_user
  db_password        = var.db_password # decrypted from SOPS via -var-file
}
```

## `moves.tf` — zero-diff state migration

```hcl
moved {
  from = aws_s3_bucket.assets_dev
  to   = module.webapp["dev"].aws_s3_bucket.assets
}
moved {
  from = aws_s3_bucket.assets_prod
  to   = module.webapp["prod"].aws_s3_bucket.assets
}
moved {
  from = aws_db_instance.dev
  to   = module.webapp["dev"].aws_db_instance.postgres
}
moved {
  from = aws_db_instance.prod
  to   = module.webapp["prod"].aws_db_instance.postgres
}
moved {
  from = aws_eks_cluster.dev
  to   = module.webapp["dev"].aws_eks_cluster.this
}
moved {
  from = aws_eks_cluster.prod
  to   = module.webapp["prod"].aws_eks_cluster.this
}
moved {
  from = aws_eks_node_group.dev
  to   = module.webapp["dev"].aws_eks_node_group.this
}
moved {
  from = aws_eks_node_group.prod
  to   = module.webapp["prod"].aws_eks_node_group.this
}
# …one moved block per former top-level dev/prod resource pair
```

## Verification

```bash
terraform init
terraform plan -var-file=prod.tfvars   # expect: "Plan: 0 to add, 0 to change, 0 to destroy"
```

## Notes

- **Zero-diff guarantee**: `moved` blocks rewrite addresses in state in-place; attributes are unchanged because module logic is identical to the old duplicated blocks. Delete the moved blocks (or keep them; they're inert after first apply).
- **Environment isolation**: `for_each` keys produce independent addresses (`module.webapp["dev"]` vs `["prod"]`), so `-target=module.webapp[\"prod\"]` never touches dev. For stronger isolation, split into workspaces later — the module carries over unchanged.
- **Secrets**: DB password stays out of Git via SOPS-encrypted tfvars (`sops -d prod.secrets.tfvars > /dev/stdout | terraform apply -var-file=-`).
- **Conditional prod-only resources** (replication, OIDC role) use `count` guarded by `var.enable_replication` / `var.oidc_provider != null` — dev plan shows `0 to add`.
